THEME = ("T05", "Contrôle d'accès par rôles (RBAC)")
SOURCE = "Ferraiolo et Kuhn, « Role-Based Access Controls », NIST, 1992 ; Sandhu et al., « Role-Based Access Control Models », IEEE Computer, 1996 ; ANSI/INCITS 359-2004 ⚠ à vérifier"
Q = [
(1,"Dans RBAC, à quoi sont directement attachées les permissions ?","Aux rôles","Aux utilisateurs","Aux fichiers uniquement","Aux adresses IP",
 "Les utilisateurs reçoivent des rôles, et les rôles portent les permissions."),
(1,"Qu'est-ce qu'un rôle en RBAC ?","Un ensemble de permissions correspondant à une fonction dans l'organisation","Un mot de passe","Un compte invité","Un type de fichier",
 "Par exemple « comptable », « magasinier » ou « gestionnaire »."),
(1,"Comment donne-t-on une nouvelle permission à 35 magasiniers en RBAC ?","On l'ajoute une fois au rôle Magasinier","On la donne à chacun individuellement","On crée 35 groupes","On change le mot de passe",
 "L'administration centrée sur le rôle évite 35 opérations et les oublis."),
(1,"Quel est le principal avantage de RBAC pour l'administration ?","Les droits suivent la fonction, pas la personne","Chaque fichier a son propre propriétaire","Il n'y a plus de mot de passe","Les rôles sont supprimés",
 "Arrivées, mutations et départs se gèrent par attribution ou retrait de rôles."),
(1,"Que se passe-t-il quand un salarié change de poste en RBAC ?","On lui retire l'ancien rôle et on lui attribue le nouveau","On copie ses droits un par un","On crée un nouveau compte","On le met administrateur",
 "Sans retrait de l'ancien rôle, les droits s'accumulent."),
(2,"Quels sont les trois éléments de base du modèle RBAC0 ?","Utilisateurs, rôles et permissions","Sujets, niveaux et catégories","Attributs, règles et décisions","Objets, ACL et journaux",
 "RBAC0 (Sandhu, 1996) comprend aussi des sessions pour activer des rôles."),
(2,"Qu'est-ce qu'une session en RBAC ?","Le contexte dans lequel un utilisateur active un sous-ensemble de ses rôles","Une réunion de formation","Un mot de passe temporaire","Un journal",
 "Activer seulement les rôles utiles à la tâche respecte le moindre privilège."),
(2,"Quel modèle ajoute une hiérarchie de rôles ?","RBAC1","RBAC0","RBAC2","RBAC3",
 "RBAC1 = RBAC0 + hiérarchie ; RBAC2 = + contraintes ; RBAC3 = les deux."),
(2,"Quel modèle ajoute des contraintes comme la séparation des tâches ?","RBAC2","RBAC0","RBAC1","DAC",
 "Les contraintes encadrent l'attribution et l'activation des rôles."),
(2,"Quel modèle combine hiérarchie et contraintes ?","RBAC3","RBAC1","RBAC2","RBAC0",
 "RBAC3 est le modèle consolidé."),
(2,"Qu'exprime la hiérarchie de rôles « Responsable hérite de Employé » ?","Le responsable possède aussi toutes les permissions de l'employé","L'employé possède celles du responsable","Les deux n'ont aucune permission","Le responsable est supprimé",
 "Le rôle supérieur hérite des permissions du rôle inférieur."),
(2,"Quel risque la hiérarchie de rôles peut-elle introduire ?","Une propagation involontaire de permissions vers les rôles supérieurs","Un blocage réseau","Une perte de journaux","Un chiffrement involontaire",
 "Un rôle ajouté en bas de la hiérarchie élargit les droits de tous les rôles qui en héritent."),
(2,"Qu'est-ce que la séparation des tâches statique (SSD) ?","Deux rôles incompatibles ne peuvent pas être attribués à la même personne","Deux rôles ne peuvent pas être actifs ensemble dans une session","Deux utilisateurs ne peuvent pas partager un rôle","Un rôle est limité à un fichier",
 "Elle s'applique au moment de l'attribution des rôles."),
(2,"Qu'est-ce que la séparation des tâches dynamique (DSD) ?","Deux rôles peuvent être attribués mais pas activés en même temps dans la même session","Deux rôles ne peuvent jamais être attribués ensemble","Un rôle expire après une heure","Un rôle est supprimé la nuit",
 "Elle s'applique à l'activation en session."),
(2,"Quelle paire de rôles est un bon exemple d'incompatibilité en séparation des tâches ?","Créer un fournisseur et valider son paiement","Consulter un planning et imprimer un planning","Se connecter et se déconnecter","Lire un courriel et répondre",
 "Cumuler ces deux rôles permettrait de créer un faux fournisseur puis de le payer."),
(1,"Quelle limite maximum a souvent la taille d'un rôle bien conçu ?","Il regroupe des permissions cohérentes avec une fonction","Il contient toutes les permissions","Il est vide","Il contient un seul utilisateur",
 "Un rôle fourre-tout est contraire au moindre privilège."),
(2,"Qu'est-ce que l'« explosion des rôles » ?","La multiplication de rôles très spécifiques difficiles à gérer","La perte du rôle administrateur","Le blocage d'un serveur","Le départ massif des utilisateurs",
 "Quand on veut tout exprimer par des rôles, leur nombre devient ingérable."),
(2,"Quel indice montre qu'il y a explosion des rôles ?","Presque autant de rôles que d'utilisateurs","Un seul rôle par service","Des rôles documentés","Une hiérarchie simple",
 "Un rôle par personne revient à du DAC déguisé."),
(2,"Qu'est-ce que le « role mining » ?","Analyser les droits existants pour en déduire des rôles","Supprimer des utilisateurs","Chiffrer des rôles","Sauvegarder des journaux",
 "Il aide à migrer d'une gestion par droits individuels vers RBAC."),
(2,"Qu'est-ce que la « dérive des rôles » (role drift) ?","Un rôle accumule peu à peu des permissions non prévues","Un rôle disparaît automatiquement","Un rôle change de nom","Un rôle devient public",
 "Sans revue, des ajouts ponctuels s'ajoutent au rôle et dépassent le besoin."),
(2,"Quelle activité contrôle périodiquement que les rôles et leurs membres restent justifiés ?","La recertification des rôles et des droits","La mise à jour du navigateur","La défragmentation","La sauvegarde",
 "Les responsables confirment ou retirent les attributions."),
(2,"Qui est le mieux placé pour valider les permissions d'un rôle métier ?","Le responsable métier concerné","Le fournisseur du matériel","Un utilisateur au hasard","Le service de nettoyage",
 "Il connaît les tâches réellement nécessaires."),
(3,"Un utilisateur a deux rôles : A (lecture) et B (écriture) sur un même objet. Quel est son droit effectif sans refus explicite ?","Lecture et écriture","Lecture seule","Écriture seule","Aucun",
 "En RBAC standard, les permissions des rôles actifs s'additionnent."),
(3,"En DSD, un utilisateur a les rôles Saisie et Validation attribués. Que se passe-t-il ?","Il ne peut les activer ensemble dans une session","Il perd les deux rôles","Il devient administrateur","Il ne peut plus se connecter",
 "Les deux restent attribués, mais l'activation conjointe est interdite."),
(2,"Qu'est-ce qu'un rôle « administrateur » mal conçu en RBAC ?","Un rôle qui regroupe toutes les permissions pour tous les services","Un rôle limité à un service","Un rôle journalisé","Un rôle temporaire",
 "Il viole le moindre privilège et crée une cible de choix pour un attaquant."),
(2,"Comment limiter l'usage d'un rôle très privilégié ?","En ne l'activant que pour la tâche et en journalisant","En le donnant à tous","En l'enlevant du journal","En partageant le mot de passe",
 "L'activation à la demande réduit la durée d'exposition."),
(2,"Le TMS de TransLor compte 120 utilisateurs et 4 rôles. Combien d'attributions rôle-utilisateur au minimum si chacun a un seul rôle ?","120","4","480","124",
 "Chaque utilisateur est rattaché à un rôle : 120 attributions."),
(3,"Combien d'attributions directes de permissions faut-il pour donner 10 permissions à 40 utilisateurs sans RBAC ?","400","50","40","10",
 "10 permissions × 40 utilisateurs = 400 ; avec un rôle, on en configure 10 puis 40 attributions."),
(3,"Avec RBAC, combien d'opérations au total pour 10 permissions et 40 utilisateurs (un rôle) ?","50","400","10","40",
 "10 permissions associées au rôle + 40 attributions de rôle = 50 opérations."),
(2,"Quel est l'inconvénient de RBAC pour des règles dépendant du contexte (heure, lieu) ?","Il ne les exprime pas nativement","Il les interdit","Il les chiffre","Il les supprime",
 "RBAC ignore l'heure, l'appareil et la situation : on complète avec ABAC ou des contraintes."),
(2,"Une règle « un gestionnaire ne modifie que les dossiers de son agence » est difficile en RBAC pur parce que :","Elle dépend d'un attribut de l'utilisateur et de la ressource","Elle utilise un rôle","Elle concerne un fichier","Elle est trop courte",
 "Sans attributs, il faudrait un rôle par agence, d'où explosion des rôles."),
(3,"Quel compromis réduit l'explosion des rôles pour une règle par agence ?","Un rôle générique complété par un attribut d'agence","Un rôle par utilisateur","Un seul rôle administrateur","La suppression des rôles",
 "On combine rôles et attributs (RBAC étendu ou ABAC) pour garder peu de rôles."),
(2,"Qu'est-ce qu'un « rôle technique » par rapport à un « rôle métier » ?","Il porte des permissions d'exploitation (sauvegarde, supervision) plutôt que des fonctions de gestion","Il est sans permission","Il est réservé aux clients","Il est supprimé après usage",
 "Distinguer rôles métier et rôles techniques clarifie les responsabilités."),
(2,"Pourquoi interdire qu'un même rôle cumule administration système et audit ?","L'auditeur contrôlerait ses propres actions","Les deux sont identiques","Le rôle serait trop court","Les journaux seraient chiffrés",
 "Séparer l'administration et le contrôle préserve l'indépendance de l'audit."),
(2,"Qu'est-ce qu'un « rôle d'urgence » (break-glass) ?","Un accès exceptionnel, tracé et rare, utilisé en cas d'incident","Un accès permanent pour tous","Un accès anonyme","Un accès supprimé",
 "Il permet de dépanner sans bloquer l'activité, avec contrôle a posteriori."),
(3,"Quel contrôle compense l'usage d'un accès break-glass ?","Une revue immédiate des actions réalisées","Aucun","Un changement de logo","La suppression du compte pour toujours",
 "L'accès d'urgence reste légitime s'il est justifié, tracé et relu."),
(2,"Quelle norme américaine a standardisé le modèle RBAC ?","ANSI/INCITS 359","RFC 2119","PCI DSS 4.0","ISO 9001",
 "La norme date de 2004 et s'appuie sur les travaux du NIST."),
(1,"Quelle entité attribue les rôles aux utilisateurs ?","L'administration, sur demande validée du responsable","L'utilisateur lui-même","Un visiteur","Le fabricant du logiciel",
 "L'attribution est un acte d'administration, tracé et validé."),
(2,"Qu'est-ce que l'« auto-attribution de rôle » et pourquoi est-elle dangereuse ?","L'utilisateur s'ajoute un rôle lui-même ; il contourne la validation","Un rôle automatique du système ; il est sans risque","Un rôle partagé entre services ; il est lent","Un rôle sans permissions ; il est inutile",
 "Les attributions doivent être approuvées par une personne différente du bénéficiaire."),
(2,"Quel principe justifie l'usage de rôles distincts pour les tâches courantes et d'administration ?","Le moindre privilège","La confidentialité absolue","La compression","La redondance",
 "Un administrateur ne devrait pas lire son courrier avec un compte à privilèges."),
(3,"Dans une hiérarchie, le rôle R3 hérite de R2 qui hérite de R1. L'ajout d'une permission à R1 :","Étend les droits de R1, R2 et R3","N'affecte que R1","N'affecte que R3","Supprime R2",
 "L'héritage est transitif : tout ce qui est donné à un rôle bas profite aux rôles hauts."),
(3,"Quel défaut l'héritage de rôles peut-il causer avec la séparation des tâches ?","Un rôle supérieur peut cumuler indirectement des permissions incompatibles","Il supprime les contraintes","Il chiffre les rôles","Il ralentit le réseau",
 "Les contraintes doivent tenir compte de l'héritage, sinon elles sont contournées."),
(1,"Pourquoi les rôles facilitent-ils les audits ?","On vérifie les permissions de quelques rôles et leurs membres plutôt que chaque utilisateur","Ils sont secrets","Ils sont toujours corrects","Ils suppriment les journaux",
 "L'auditeur raisonne par rôle : plus lisible que des milliers de droits individuels."),
(2,"Quel indicateur révèle un rôle surdimensionné ?","Beaucoup de permissions jamais utilisées par ses membres","Aucun membre","Un nom court","Un seul utilisateur",
 "L'analyse d'usage montre ce qui peut être retiré."),
(2,"Quelle action réduit le risque d'accumulation de rôles lors des mutations ?","Retirer systématiquement les anciens rôles au changement de poste","Ajouter toujours le nouveau rôle seulement","Donner le rôle administrateur","Supprimer le journal",
 "Le processus mutation doit inclure le retrait des rôles devenus inutiles."),
(2,"Comment appelle-t-on l'accumulation de rôles successifs chez un même salarié ?","Le cumul de privilèges (privilege creep)","L'héritage de session","La fédération","La rotation des clés",
 "Il traduit l'absence de retrait lors des mobilités."),
(3,"Quelle estimation de « droits en trop » obtient-on si 20 salariés ont chacun 3 rôles superflus sur 5 ?","60 attributions superflues","15","100","5",
 "20 × 3 = 60 attributions de rôles à retirer lors d'une recertification."),
]
